head.script:
var ganttChart = null;

/**
 * DHTMLX Gantt CSS 동적 로딩
 */
function loadDhtmlxCSS() {
    return new Promise(function(resolve, reject) {
        var link = document.createElement('link');
        link.rel = 'stylesheet';
        link.href = 'https://cdn.dhtmlx.com/gantt/edge/dhtmlxgantt.css';
        link.onload = function() {
            console.log("DHTMLX Gantt CSS 로딩 완료");
            resolve();
        };
        link.onerror = function() {
            console.error("DHTMLX Gantt CSS 로딩 실패");
            reject();
        };
        document.head.appendChild(link);
    });
}

/**
 * DHTMLX Gantt 라이브러리 로딩 확인
 */
function waitForDhtmlxGantt(callback) {
    if (typeof gantt !== 'undefined') {
        callback();
    } else {
        setTimeout(function() {
            waitForDhtmlxGantt(callback);
        }, 100);
    }
}

scwin.onpageload = function () {
    console.log("DHTMLX Gantt 간트차트 페이지 로딩 시작");

    // 1단계: CSS 동적 로딩
    loadDhtmlxCSS().then(function() {
        console.log("CSS 로딩 성공, Gantt 라이브러리 확인 중...");

        // 2단계: Gantt 라이브러리 확인
        waitForDhtmlxGantt(function() {
            console.log("DHTMLX Gantt 라이브러리 로딩 완료");

            // 3단계: 간트차트 초기화 후 데이터 로딩
            setTimeout(function() {
                scwin.initGanttConfig();
                scwin.loadTaskList();
            }, 300); // CSS 완전 적용 대기
        });
    }).catch(function() {
        console.error("CSS 로딩 실패");
        scwin.showErrorState("CSS 로딩에 실패했습니다.");
    });
};

/**
 * DHTMLX Gantt 설정 초기화
 */
scwin.initGanttConfig = function() {
    try {
        // 기본 설정
        gantt.config.date_format = "%Y-%m-%d";
        gantt.config.xml_date = "%Y-%m-%d";
        gantt.config.duration_unit = "day";

        // 최신 스케일 설정 (경고 메시지 해결)
        gantt.config.scales = [
            {unit: "month", step: 1, format: "%Y년 %m월"},
            {unit: "day", step: 1, format: "%d일"}
        ];

        // 한국어 설정
        gantt.config.fit_tasks = true;
        gantt.config.autosize = "y";
        gantt.config.row_height = 40;
        gantt.config.scale_height = 60;
        gantt.config.sort = true;

        // 컬럼 설정
        gantt.config.columns = [
            {name: "text", label: "업무명", width: 200, tree: true},
            {name: "stage", label: "단계", width: 80, align: "center"},
            {name: "status", label: "상태", width: 70, align: "center", template: function(task) {
                return '<span class="status_badge ' + scwin.getStatusClass(task.status) + '">' + (task.status || '대기') + '</span>';
            }},
            {name: "assignee", label: "담당자", width: 80, align: "center"},
            {name: "progress", label: "진척률", width: 60, align: "center", template: function(task) {
                return Math.round(task.progress * 100) + "%";
            }},
            {name: "start_date", label: "시작일", width: 80, align: "center"},
            {name: "duration", label: "기간", width: 50, align: "center"}
        ];

        // 작업 클래스 템플릿 (상태별 색상)
        gantt.templates.task_class = function(start, end, task) {
            var status = task.status || "waiting";
            return "status_" + status.replace(" ", "_");
        };

        // 작업 텍스트 템플릿
        gantt.templates.task_text = function(start, end, task) {
            var duration = gantt.calculateDuration(start, end);
            return task.text + " (" + duration + "일)";
        };

        // 툴팁 템플릿
        gantt.templates.tooltip_text = function(start, end, task) {
            var duration = gantt.calculateDuration(start, end);
            return "<b>업무:</b> " + task.text + "<br/>" +
                   "<b>단계:</b> " + (task.stage || "기타") + "<br/>" +
                   "<b>상태:</b> " + (task.status || "대기") + "<br/>" +
                   "<b>담당자:</b> " + (task.assignee || "미지정") + "<br/>" +
                   "<b>시작일:</b> " + gantt.templates.task_date(start) + "<br/>" +
                   "<b>종료일:</b> " + gantt.templates.task_date(end) + "<br/>" +
                   "<b>기간:</b> " + duration + "일<br/>" +
                   "<b>진척률:</b> " + Math.round(task.progress * 100) + "%";
        };

        // 간트차트 초기화
        gantt.init("ganttCanvas");

        console.log("DHTMLX Gantt 설정 초기화 완료");

    } catch (error) {
        console.error("Gantt 설정 초기화 오류:", error);
        scwin.showErrorState("간트차트 설정 초기화 실패: " + error.message);
    }
};

scwin.loadTaskList = function() {
    console.log("업무 목록 조회 요청");
    $c.sbm.execute($p, sbm_selectTaskList);
};

scwin.sbm_selectTaskList_submitdone = function(e) {
    try {
        console.log("서버 응답 수신:", e.responseJSON);
        var elData = e.responseJSON.elData;

        if (elData && elData.designVoList && elData.designVoList.length > 0) {
            console.log("업무 데이터 개수:", elData.designVoList.length);
            dlt_designVoList.setJSON(elData.designVoList);

            // DHTMLX Gantt 확인 후 차트 생성
            if (typeof gantt !== 'undefined') {
                scwin.createGanttChart();
            } else {
                console.error("DHTMLX Gantt가 로드되지 않았습니다.");
                scwin.showErrorState("DHTMLX Gantt 라이브러리 로딩 실패");
            }
        } else {
            console.log("업무 데이터가 없음");
            scwin.showEmptyState();
        }
    } catch (error) {
        console.error("데이터 처리 오류:", error);
        scwin.showErrorState("데이터를 처리하는 중 오류가 발생했습니다.");
    }
};

/**
 * DHTMLX Gantt 차트 생성
 */
scwin.createGanttChart = function() {
    try {
        var taskData = dlt_designVoList.getAllJSON();

        if (!taskData || taskData.length === 0) {
            scwin.showEmptyState();
            return;
        }

        // DHTMLX Gantt 데이터 형식으로 변환
        var ganttData = {
            data: [],
            links: []
        };

        taskData.forEach(function(task, index) {
            var taskId = task.taskId || String(index + 1);
            var taskName = task.taskName || ("업무 " + (index + 1));
            var stageName = task.stgName || "기타";
            var taskStatus = task.taskStatus || "대기";
            var assignee = task.taskAsi || "미지정";
            var progress = parseFloat(task.taskRate || "0") / 100;

            // 시작일과 종료일 설정 (예정일정 우선, 없으면 실제일정)
            var startDate = task.taskSt || task.taskRst;
            var endDate = task.taskEt || task.taskRet;

            // 날짜가 없는 경우 기본값 설정
            if (!startDate) {
                startDate = "2025-01-01";
            }
            if (!endDate) {
                var start = new Date(startDate);
                start.setDate(start.getDate() + 30);
                endDate = start.toISOString().split('T')[0];
            }

            var ganttTask = {
                id: taskId,
                text: taskName,
                start_date: startDate,
                end_date: endDate,
                duration: gantt.calculateDuration(new Date(startDate), new Date(endDate)),
                progress: progress,
                stage: stageName,
                status: taskStatus,
                assignee: assignee,
                open: true
            };

            ganttData.data.push(ganttTask);
        });

        // 간트차트에 데이터 파싱
        gantt.clearAll();
        gantt.parse(ganttData);

        console.log("DHTMLX Gantt 차트 생성 완료 - 업무 수:", taskData.length);

    } catch (error) {
        console.error("간트차트 생성 오류:", error);
        scwin.showErrorState("간트차트를 생성하는 중 오류가 발생했습니다: " + error.message);
    }
};

/**
 * 상태별 CSS 클래스 반환
 */
scwin.getStatusClass = function(status) {
    var classes = {
        '대기': 'status_waiting',
        '진행중': 'status_progress', 
        '완료': 'status_completed',
        '지연': 'status_delayed'
    };
    return classes[status] || 'status_waiting';
};

/**
 * 텍스트 자르기
 */
scwin.truncateText = function(text, maxLength) {
    if (!text) return '';
    return text.length > maxLength ? text.substring(0, maxLength) + '...' : text;
};

/**
 * 날짜 포맷팅
 */
scwin.formatDate = function(date) {
    try {
        return date.toLocaleDateString('ko-KR', {
            year: 'numeric',
            month: '2-digit',
            day: '2-digit'
        });
    } catch (e) {
        return date.toString();
    }
};

scwin.showEmptyState = function() {
    try {
        var chartWrapper = document.querySelector('.chart_canvas_wrapper');
        if (chartWrapper) {
            chartWrapper.innerHTML = '<div class="loading_state">표시할 업무가 없습니다</div>';
        }
    } catch (error) {
        console.error("빈 상태 표시 오류:", error);
    }
};

scwin.showErrorState = function(message) {
    try {
        var chartWrapper = document.querySelector('.chart_canvas_wrapper');
        if (chartWrapper) {
            chartWrapper.innerHTML = '<div class="error_state">' + message + '</div>';
        }
    } catch (error) {
        console.error("에러 상태 표시 오류:", error);
    }
};

// 버튼 이벤트
scwin.refreshData = function() {
    scwin.loadTaskList();
};

scwin.goToListPage = function() {
    $p.url("/InsWebApp/ui/task/design/DesignList.xml");
};


// 뷰 변경 함수들 (새로운 스케일 방식)
scwin.changeToMonthView = function() {
    try {
        gantt.config.scales = [
            {unit: "month", step: 1, format: "%Y년 %m월"},
            {unit: "day", step: 1, format: "%d"}
        ];
        gantt.render();
    } catch (error) {
        console.error("월별 보기 변경 오류:", error);
    }
};

scwin.changeToWeekView = function() {
    try {
        gantt.config.scales = [
            {unit: "week", step: 1, format: "%Y년 %W주"},
            {unit: "day", step: 1, format: "%d"}
        ];
        gantt.render();
    } catch (error) {
        console.error("주별 보기 변경 오류:", error);
    }
};

scwin.changeToDayView = function() {
    try {
        gantt.config.scales = [
            {unit: "day", step: 1, format: "%m월 %d일"}
        ];
        gantt.render();
    } catch (error) {
        console.error("일별 보기 변경 오류:", error);
    }
};
